import { L, info, mc, tf, fill, fillc, type, order, match } from '../_h.js';

export default {
  quantization: [
    L('Why make numbers smaller?',
      info('Models are just numbers', 'A trained network is millions of weights. By default each one is a **32-bit float**: 4 bytes.\n\nA model with 25 million weights needs about 100 MB. Many devices cannot afford that, and float maths is slow or missing on small chips.\n\n**Quantisation** stores each number in fewer bits, usually 8.'),
      mc('A weight stored as float32 uses how many bytes?', ['4', '1', '8', '32'], '32 bits = 4 bytes.'),
      type('A float32 model is 100 MB. About how many MB is it after 8-bit quantisation?', ['25', '25 mb', '25mb'], '8 bits is a quarter of 32 bits.'),
      info('The price', 'An 8-bit integer has only **256** possible values. Every float must be rounded to the nearest one, so a small error is added to each weight and activation.\n\nGood quantisation keeps that error small enough that accuracy barely changes.'),
      mc('How many different values can an 8-bit integer hold?', ['256', '8', '128', '1024'], '2 to the power 8.'),
      tf('Quantisation usually makes a model more accurate.', false, 'It trades a little accuracy for size and speed.'),
      match('Match the benefit to its cause', [['Smaller file', 'Fewer bits per weight'], ['Faster on CPUs', 'Integer maths and better cache use'], ['Runs on microcontrollers', 'No floating-point unit needed'], ['Lower energy use', 'Less memory traffic']]),
      mc('Which device benefits most from quantisation?', ['A battery-powered camera with a small CPU', 'A training cluster with 8 GPUs', 'A laptop running a spreadsheet', 'A database server'], 'Edge devices have tight memory, power and compute budgets.')),

    L('Scale and zero point',
      info('Mapping floats to integers', 'We map a float range onto the integer range with two numbers:\n\n```\nq = round(x / scale) + zero_point\nx ≈ (q - zero_point) * scale\n```\n\n**scale** is the size of one integer step. **zero_point** is the integer that represents 0.0.'),
      type('scale = 0.1, zero_point = 0. What integer represents x = 2.5?', ['25'], 'round(2.5 / 0.1) + 0 = 25.'),
      type('scale = 0.5, zero_point = 10. What float does q = 14 represent?', ['2', '2.0'], '(14 - 10) * 0.5 = 2.0.'),
      fillc('scale = (xmax - xmin) / (___)', ['qmax - qmin', 'qmax + qmin', 'xmax * qmax', '256 * xmin'], 'The float range is spread over the integer range.'),
      info('Why zero must be exact', 'Zero is special: padding is zero, and ReLU outputs many exact zeros. If 0.0 were rounded to something else, every padded pixel would carry an error.\n\nSo the zero point is chosen so that 0.0 maps to an integer **exactly**.'),
      mc('Activations after ReLU lie in [0, 6]. With signed int8 (-128..127), which integer should represent 0.0?', ['-128', '0', '127', '6'], 'All values are non-negative, so use the whole range: 0.0 sits at the bottom.'),
      mc('What happens to a value outside the calibrated range?', ['It is clipped (saturates) to the nearest end', 'It wraps around to a negative number', 'It is stored as a float', 'The model crashes'], 'Clipping is designed in; wrap-around would be a bug.'),
      tf('Symmetric quantisation uses a zero point of 0.', true, 'It is the usual choice for weights, which are roughly centred on zero.')),

    L('PTQ, QAT and calibration',
      info('Two ways to get there', '**Post-training quantisation (PTQ):** take a trained model, run a few hundred real samples through it to measure the range of every activation, choose scales. No retraining.\n\n**Quantisation-aware training (QAT):** insert fake rounding during training so the weights learn to live with it. More work, better accuracy.'),
      mc('What is the calibration set used for in PTQ?', ['Measuring activation ranges', 'Updating the weights', 'Computing test accuracy', 'Choosing the learning rate'], 'Weights are known; activation ranges depend on data.'),
      mc('One activation has values mostly in [0, 4] but a rare outlier at 400. Using min/max calibration…', ['Wastes almost all integer levels on empty range', 'Is optimal', 'Makes the model exact', 'Removes the outlier'], 'Clip with a percentile or entropy method so common values keep resolution.'),
      info('Rounding has no gradient', 'In QAT the forward pass rounds, but rounding is flat almost everywhere, so its gradient is zero.\n\nThe trick is the **straight-through estimator**: in the backward pass, pretend rounding was the identity function.'),
      fill('In QAT, gradients pass through the rounding step using the ___ estimator.', ['straight-through', 'maximum-likelihood', 'Kalman', 'bootstrap'], 'Forward: round. Backward: identity.'),
      order('Put the PTQ workflow in order', ['Train the float model', 'Collect a small representative calibration set', 'Run it through the model and record activation ranges', 'Compute scales and zero points', 'Compare accuracy with the float model'], 'Always finish by measuring the accuracy drop.'),
      mc('PTQ costs 6% accuracy on your small model. Best next step?', ['Try per-channel weights and better calibration, then QAT', 'Ship it', 'Quantise to 4 bits instead', 'Remove the calibration set'], 'Cheap fixes first, then QAT.'),
      tf('Per-channel quantisation gives each output channel of a convolution its own scale.', true, 'Channels can differ in range by orders of magnitude.')),

    L('Fixed point and interview level',
      info('No floats at all', 'On a microcontroller the scale itself cannot be a float. It becomes an **integer multiplier and a right shift**.\n\nSignal code often uses **Q format**: in Q15 an int16 value `v` means `v / 32768`, covering -1 to just under +1.'),
      type('In Q15, which integer represents 0.5?', ['16384'], '0.5 * 32768 = 16384.'),
      mc('You multiply two Q15 numbers as integers. The raw product is in which format?', ['Q30', 'Q15', 'Q16', 'Q7'], 'Fractional bits add: 15 + 15. Shift right by 15 to return to Q15.'),
      fillc('int32_t p = (int32_t)a * b;\nint16_t r = (int16_t)((p + (1 << 14)) ___ 15);', ['>>', '<<', '&', '%'], 'Add half a step for rounding, then shift right.'),
      mc('In Q15, -1.0 × -1.0 should be +1.0, which is not representable. Correct behaviour?', ['Saturate to 32767', 'Wrap to -32768', 'Return 0', 'Raise an exception'], 'Wrap-around flips the sign, which is dangerous in control code.'),
      info('Debugging a bad quantised model', 'Interviewers love this question. A solid answer:\n\n1. Compare float and quantised outputs **layer by layer** to find where error appears.\n2. Check the calibration data is representative.\n3. Try per-channel weights and clipped ranges.\n4. Keep sensitive layers (often first and last) at higher precision.\n5. Use QAT.'),
      mc('Accuracy collapses right after one specific layer. Sensible fix?', ['Keep that layer in float or 16-bit (mixed precision)', 'Quantise everything to 4 bits', 'Delete the layer', 'Retrain from scratch with a new seed'], 'Mixed precision spends bits where they matter.'),
      mc('Why can 4-bit quantisation of an LLM still work well?', ['Large models are redundant, and methods like GPTQ or AWQ choose rounding to minimise output error', 'LLMs do not use weights', '4-bit is lossless', 'It only quantises the tokenizer'], 'They calibrate on data and correct for the error layer by layer.'),
      match('Match the term', [['PTQ', 'Quantise after training with calibration data'], ['QAT', 'Simulate rounding during training'], ['Zero point', 'Integer that represents 0.0'], ['Saturation', 'Clamp to the range limits']])),

    L('Symmetric, per-channel and the int32 accumulator',
      info('Symmetric or asymmetric?', 'Two ways to place the integer grid on the float range.\n\n**Symmetric:** the range is `[-m, +m]`, where `m` is the largest absolute value, and the zero point is 0. For int8 it is common to use -127 to 127, so `scale = m / 127`.\n\n**Asymmetric:** the range is `[min, max]` and the zero point shifts to fit. It wastes fewer levels when data is one-sided, such as ReLU outputs.\n\nSymmetric is simpler and faster (no zero-point terms in the maths), so it is the usual choice for weights.'),
      mc('Which choice is usual for convolution weights, which are roughly centred on zero?', ['Symmetric, with zero point 0', 'Asymmetric, with a large zero point', 'Unsigned 8-bit with zero point 255', 'No quantisation at all'], 'Centred data needs no shift, and a zero point of 0 simplifies the integer maths.'),
      type('Symmetric int8 using -127 to 127. The largest absolute weight is 6.35. What is the scale?', ['0.05'], '6.35 / 127 = 0.05.'),
      info('Accumulators and requantisation', 'An int8 × int8 product can reach 16384 in size, and a convolution sums hundreds of them. So the sum is kept in an **int32 accumulator**.\n\nThe result must then be squeezed back to int8 for the next layer. This **requantisation** multiplies by the real number `s_x × s_w / s_out`, which on integer hardware becomes a fixed integer multiplier followed by a right shift.'),
      mc('Why does a convolution accumulate int8 products in an int32?', ['The sum of many products overflows 16 bits', 'int32 is more accurate than float', 'int8 values cannot be multiplied', 'It saves memory'], 'Each product can reach 16384, so only a couple of them already exceed the int16 range.'),
      type('What is the largest product of two int8 values (range -128 to 127)?', ['16384'], '(-128) × (-128) = 16384.'),
      match('Match the term', [['Static quantisation', 'Activation scales fixed in advance from calibration data'], ['Dynamic quantisation', 'Activation ranges measured at run time'], ['Folded batch norm', 'Merged into the previous layer’s weights and bias'], ['Requantisation', 'Rescaling the int32 result back to int8']]),
      tf('Batch normalisation can be folded into the preceding convolution before quantising.', true, 'At inference time batch norm is a fixed scale and shift, so it merges into the weights and bias.'),
      fill('On integer-only hardware, the real rescale factor becomes an integer multiplier and a ___.', ['right shift', 'left shift', 'square root', 'modulo'], 'Multiply, then shift right: no floating point is needed.'),
      mc('A residual block adds two int8 tensors whose scales are 0.1 and 0.2. What must happen before the integers are added?', ['Rescale one or both to a common scale', 'Nothing: add the integers directly', 'Convert both to strings', 'Drop the smaller tensor'], 'The same integer means different real values: 5 at scale 0.1 is 0.5, but 5 at scale 0.2 is 1.0.')),

    L('Fixed-point bugs and how to catch them',
      info('Bug 1: the narrow accumulator', 'A dot product of int8 data in C looks harmless, yet it fails on real data. The sum is kept in a 16-bit variable and **wraps around** once the total passes 32767.\n\nIt passes small tests because small tests have small numbers. The accumulator must be `int32_t`, and you should work out the worst-case sum on paper: number of terms × largest product.'),
      mc('A quantised dot product is correct on a few test vectors but wrong on real data. What is the bug?', ['The 16-bit accumulator overflows and wraps', 'int8 multiplication is not allowed in C', 'The loop runs one time too few', 'The weights are stored in flash'], 'Products add up quickly: use an int32_t accumulator.', 'int16_t acc = 0;\nfor (int i = 0; i < 64; i++) {\n    acc += w[i] * x[i];\n}'),
      type('Each product is 10000 and an int16 holds up to 32767. How many products can be added before it overflows?', ['3'], '3 × 10000 = 30000 fits; 4 × 10000 = 40000 does not.'),
      info('Bug 2: rounding, wrap-around and clipping', 'An arithmetic right shift always rounds **down** (towards minus infinity): `-3 >> 1` is `-2`. The C standard leaves the shift of negative values implementation-defined, but common compilers use an arithmetic shift. Plain truncation also biases results downwards, so add half a step before shifting.\n\nCasting an out-of-range int to `int8_t` is implementation-defined too, and typically wraps: `(int8_t)200` becomes `-56`. Always **clamp first**.'),
      type('With an arithmetic shift, what is -3 >> 1 in C?', ['-2'], 'The result rounds down: -1.5 becomes -2.'),
      mc('On a typical compiler, what does (int8_t)200 give?', ['-56', '127', '200', '0'], '200 wraps modulo 256 to -56. Clamp to 127 first if you mean saturation.'),
      fillc('if (v > 127) return 127;\nif (v ___ -128) return -128;', ['<', '>', '==', '!='], 'The lower clamp applies when the value is below -128.'),
      order('Order the lines of a saturating conversion', ['static inline int8_t sat8(int32_t v) {', '    if (v > 127) return 127;', '    if (v < -128) return -128;', '    return (int8_t)v;', '}'], 'Clamp both ends, then the cast is safe.'),
      mc('A quantised audio model works on quiet recordings but distorts and misclassifies loud ones. Calibration used only quiet clips. Most likely cause?', ['Loud values exceed the calibrated range and saturate', 'The accumulator is too wide', 'The model has too many layers', 'Flash memory is full'], 'Calibrate on data that covers the real range, including the loud cases.'),
      mc('Your C code differs from the Python integer reference by exactly 1 on about half of the outputs. C uses `(acc * m) >> 15`, Python rounds to nearest. Likely cause?', ['C truncates (rounds down) where Python rounds to nearest', 'The compiler is broken', 'Python uses 8-bit integers', 'Flash wear'], 'Add 1 << 14 before the shift so both round the same way.')),

    L('Case study: keyword spotting on a tiny chip',
      info('The brief', 'A battery-powered sensor must listen for one spoken keyword, always on. The float32 model has **250,000** weights. The chip has 512 KB of flash, 128 KB of RAM and no floating-point unit.\n\nAlways-on keyword spotting with int8 models on small microcontrollers is a standard industry use. You make the decisions.'),
      type('How many bytes do the 250,000 weights need after int8 quantisation?', ['250000', '250,000', '250 000'], '250,000 × 1 byte.'),
      mc('As float32 the weights would need about 1,000,000 bytes. Which first move best fits the budget?', ['Post-training int8 quantisation with a calibration set', 'Buy a bigger chip', 'Delete every second layer', 'Train for more epochs'], 'It cuts the weights to a quarter without retraining, so it is the cheapest thing to try first.'),
      info('Calibration decides the ranges', 'Activation ranges come from the calibration data. If it is clean studio speech but the product hears a kitchen or a street, real signals will clip or use too few levels.\n\nGood calibration data: several hundred clips with many speakers, distances and noise types, recorded with the real microphone.'),
      mc('Which calibration set do you choose?', ['Several hundred clips from the real microphone in varied noise', 'Ten clips of one clean voice', 'Random numbers generated with numpy', 'The training labels'], 'Ranges are measured on data, so the data must look like deployment.'),
      mc('After PTQ the detection rate falls from 94% to 89%. Best next step?', ['Try per-channel weights and a clipped range first; use QAT if it is still too low', 'Ship it: 5% is normal', 'Remove the keyword', 'Switch to 2 bits'], 'Cheap fixes first, then quantisation-aware training.'),
      mc('The largest layer output has 40,000 activations. How much RAM does that one buffer need in int8 and in float32?', ['40,000 bytes and 160,000 bytes', '160,000 bytes and 40,000 bytes', '40,000 bytes in both', '4,000 bytes and 16,000 bytes'], 'int8 is 1 byte and float32 is 4 bytes; the float buffer alone would not fit in 128 KB.'),
      order('Order the rollout', ['Train the float model', 'Quantise with a representative calibration set', 'Compare accuracy with the float model, layer by layer if needed', 'Convert to C arrays or a micro runtime', 'Measure flash, RAM, latency and energy on the device', 'Field-test with real users'], 'Verify at every hand-over, and finish on the real device.'),
      tf('If the quantised model scores well in a PC simulation, measuring on the device is optional.', false, 'Integer kernels, timing and memory only show their true behaviour on the target.'),
      mc('Which result lets you sign off the model?', ['Accuracy drop within the agreed limit on field-like data, and RAM, flash, latency and energy within budget on the device', 'The model file is smaller than before', 'The code compiles', 'The training loss went down'], 'Sign-off needs the product requirements met on the real hardware.')),

    L('Interview drill: quantisation',
      info('The questions you will hear', 'Interviewers rarely ask for a definition and stop. They ask one question, then **follow up** on your answer: "why?", "what if it fails?", "how did you measure it?".\n\nPrepare each answer as a short chain: the idea, the reason, the trade-off, and how you would check it.'),
      mc('"Why is int8 inference usually faster than float32?" Which answer is strongest?', ['Less memory traffic, and integer units can process more values per instruction', 'Because 8 is smaller than 32', 'Because integers are always more accurate', 'Because the weights are removed'], 'Both memory movement and arithmetic throughput improve.'),
      mc('Follow-up: "Does int8 always give a 4× speed-up?" Best reply?', ['No: unsupported operations fall back to float, conversions add cost, and some models are limited by memory or other stages', 'Yes, always exactly 4×', 'Yes, but only on GPUs', 'No, it is always slower'], 'Size shrinks 4×; speed depends on hardware support and the rest of the pipeline.'),
      order('Order a strong answer to "How would you quantise a model for an edge device?"', ['State the constraints: memory, latency and allowed accuracy drop', 'Start with post-training quantisation and a representative calibration set', 'Measure accuracy against the float model, layer by layer', 'Fix problems: per-channel, clipped ranges, mixed precision, then QAT', 'Verify latency and memory on the target device'], 'Constraints, cheap method, measurement, fixes, target check.'),
      info('Numbers to have ready', '- float32 to int8: **4× smaller**.\n- int8 has **256** levels.\n- `scale = (xmax - xmin) / (qmax - qmin)`.\n- Symmetric int8 scale: `max_abs / 127`.\n- Q15: an int16 divided by 32768, and a product needs a shift right by 15.\n\nQuote a number, then say how you would verify it.'),
      type('Symmetric int8 with -127 to 127. The largest absolute value is 12.7. What is the scale?', ['0.1'], '12.7 / 127 = 0.1.'),
      tf('Saying "int8 is lossless" in an interview is a red flag.', true, 'Quantisation is an approximation; always report the measured accuracy drop.'),
      match('Match the interviewer’s question to what it tests', [['Why per-channel?', 'Whether you know ranges differ between channels'], ['What if accuracy drops?', 'Your debugging method'], ['How do you multiply two Q15 numbers?', 'Fixed-point arithmetic skills'], ['PTQ or QAT?', 'Trade-off thinking']]),
      mc('You report "only 0.3% accuracy drop". What should a good interviewer ask?', ['Measured on which data, and is it representative of deployment, including worst-case classes?', 'Which colour was the plot?', 'Why not 0%?', 'Is the model file named correctly?'], 'An average drop on a clean set can hide failures on the cases that matter.'))
  ],

  'cpp-deploy': [
    L('From Python to a binary',
      info('Why not ship Python?', 'Python is great for training. In a car, a robot or a phone you often need **C or C++**: no interpreter, tight control of memory, predictable timing.\n\nThe usual route: train in PyTorch, **export** the model to a file, **load** it from C++ with an inference runtime.'),
      mc('Which format is the most common bridge between frameworks and runtimes?', ['ONNX', 'CSV', 'Pickle', 'PNG'], 'ONNX describes the graph and weights in a framework-neutral way.'),
      match('Match the runtime to where it shines', [['TensorRT', 'NVIDIA GPUs'], ['OpenVINO', 'Intel CPUs and accelerators'], ['ONNX Runtime', 'Portable across platforms'], ['TFLite / LiteRT', 'Phones and small devices']]),
      order('Order the deployment steps', ['Train the model in Python', 'Export it to ONNX', 'Check the exported model against the original', 'Load it in C++ with a runtime', 'Compare C++ outputs with Python outputs'], 'Verify at every hand-over.'),
      tf('You should create the inference session once and reuse it for every frame.', true, 'Loading a model is slow; do it at start-up.'),
      mc('Why fix the input shape at export when you can?', ['The runtime can optimise memory and kernels for it', 'ONNX forbids dynamic shapes', 'It improves accuracy', 'It hides the weights'], 'Dynamic shapes work but limit optimisation.'),
      mc('C and C++ are compiled. What does that mean?', ['Source is translated to machine code before it runs', 'It is interpreted line by line', 'It needs a virtual machine', 'It cannot use libraries'], 'Hence speed, and no interpreter on the target.')),

    L('Preprocessing parity',
      info('The bug that bites everyone', 'Your C++ model gives slightly different, or very wrong, answers. Nine times out of ten the model is fine and the **preprocessing differs**.\n\nCheck: channel order, memory layout, resize method, scaling and normalisation, data type.'),
      mc('OpenCV loads colour images in which channel order?', ['BGR', 'RGB', 'HSV', 'CMYK'], 'Most models were trained on RGB, so convert.'),
      info('HWC and CHW', 'An image in memory is **H × W × C**: pixels stored one after another, each with its channels (interleaved).\n\nMost models expect **C × H × W**: the whole red plane, then green, then blue (planar).\n\nSame numbers, different order.'),
      type('A tensor has shape (480, 640, 3) in HWC. What is its shape in CHW? Write it like (a, b, c).', ['(3, 480, 640)', '(3,480,640)', '3, 480, 640', '3,480,640'], 'Channels move to the front.'),
      fillc('// index of pixel (h, w), channel c in a CHW buffer\nsize_t i = c * H * W + h * W + ___;', ['w', 'c', 'h * W', 'H'], 'Planes of H*W values, each row W long.'),
      order('Order a typical image preprocessing pipeline', ['Convert BGR to RGB', 'Resize to the model input size', 'Convert uint8 to float and scale to 0..1', 'Subtract mean and divide by std per channel', 'Rearrange HWC to CHW'], 'Normalisation can come after the layout change too; the key is to match training.'),
      mc('Best way to prove your C++ preprocessing matches Python?', ['Dump both tensors for the same image and compare element by element', 'Look at the output picture', 'Trust the documentation', 'Compare file sizes'], 'A max absolute difference near zero is the proof.'),
      tf('Using bilinear resize in Python and nearest-neighbour in C++ can change predictions.', true, 'Interpolation is part of the model input.')),

    L('C++ that interviewers ask about',
      info('RAII', '**Resource Acquisition Is Initialisation**: tie every resource (memory, file, session) to an object. When the object goes out of scope, its destructor releases the resource.\n\nNo `delete`, no leaks on early return or exception.'),
      mc('Which smart pointer should be your default?', ['std::unique_ptr', 'std::shared_ptr', 'std::auto_ptr', 'a raw new'], 'Single owner, zero overhead. Use shared_ptr only for shared ownership.'),
      fillc('auto session = std::___<Session>(env, path);', ['make_unique', 'new_ptr', 'allocate', 'make_raw'], 'make_unique creates the object and its unique_ptr safely.'),
      mc('How should a function read a large tensor it does not modify?', ['void f(const Tensor& t)', 'void f(Tensor t)', 'void f(Tensor* t = new Tensor)', 'void f(Tensor&& t) always'], 'A const reference avoids a copy and promises no modification.'),
      info('The hot loop', 'Real-time code runs the same loop thousands of times. Inside it:\n\n- **no heap allocation** (`new`, growing vectors): slow and unpredictable\n- reuse buffers allocated at start-up\n- no logging to disk, no locks you can avoid'),
      mc('What is wrong here?', ['It allocates a new vector on every frame', 'vector cannot hold floats', 'while loops are forbidden', 'Nothing'], 'Declare the buffer once outside the loop and reuse it.', 'while (camera.read(frame)) {\n    std::vector<float> input(3 * 224 * 224);\n    preprocess(frame, input);\n    run(input);\n}'),
      mc('What does std::move do?', ['Casts to an rvalue so resources can be transferred instead of copied', 'Copies the object', 'Deletes the object', 'Moves memory to the GPU'], 'After a move, the source is valid but unspecified.'),
      match('Match the bug to the tool that finds it', [['Out-of-bounds write', 'AddressSanitizer'], ['Signed overflow', 'UndefinedBehaviorSanitizer'], ['Data race', 'ThreadSanitizer'], ['Style and common mistakes', 'clang-tidy']])),

    L('Embedded C and interview level',
      info('Models as plain C', 'On a microcontroller there may be no runtime at all. The model becomes ordinary C:\n\n- a decision tree becomes nested `if / else`\n- a small network becomes loops over `static const` arrays\n\nNo heap, fixed sizes, often fixed-point numbers.'),
      order('Arrange the generated C for a one-split tree', ['float predict(const float *x) {', '    if (x[0] <= 2.5f) {', '        return 1.0f;', '    } else {', '        return 0.0f;', '    }', '}'], 'Left branch when the condition is true.'),
      mc('Why store weights as `static const` arrays?', ['They are placed in flash (read-only memory) and use no RAM', 'They become faster floats', 'const enables the GPU', 'It makes them dynamic'], 'RAM is the scarcest resource on small devices.'),
      mc('Python computes in float64 and your C code in float32. What should a back-to-back test use?', ['A small tolerance, not exact equality', 'Exact equality', 'String comparison', 'No comparison'], 'Different precision gives tiny differences. Integer-only code can be bit-exact.'),
      tf('Recursion is commonly forbidden in safety-related embedded C.', true, 'Stack use must be bounded and analysable.'),
      info('A strong interview answer', '"How do you move a model from Python to C/C++?"\n\n1. Export and validate the export.\n2. Choose a runtime, or generate C for small models.\n3. Reimplement pre/postprocessing and prove parity tensor by tensor.\n4. Allocate once, reuse buffers.\n5. Back-to-back tests with recorded vectors.\n6. Measure latency, memory and worst case on the target.'),
      mc('Outputs differ between Python and C. Most systematic way to find the cause?', ['Compare intermediate values stage by stage until the first mismatch', 'Rewrite everything', 'Increase the tolerance until tests pass', 'Change the compiler'], 'Bisect the pipeline.'),
      mc('Which is undefined behaviour in C++?', ['Reading past the end of an array', 'Dividing two floats', 'Calling a const method', 'Using std::vector'], 'It may appear to work, then fail in production.')),

    L('Strides, caches and threads',
      info('Strides: one buffer, many views', 'A tensor is a pointer plus a shape plus **strides**: the step, in elements, between neighbours along each axis.\n\nFor a contiguous row-major tensor of shape `(C, H, W)` the strides are `(H × W, W, 1)`, so element `(c, h, w)` sits at offset `c × H × W + h × W + w`.\n\nA view can change shape or strides without copying: a crop or a transposed view reuses the same memory. But such a view is often **not contiguous**.'),
      type('A contiguous float tensor has shape (3, 224, 224). What is the stride of the first axis, in elements?', ['50176'], '224 × 224 = 50176.'),
      mc('A contiguous HWC buffer has shape (480, 640, 3). How many elements do you step to move down one row?', ['1920', '640', '3', '921600'], '640 pixels × 3 channels per pixel.'),
      info('Cache lines and contiguous memory', 'The CPU does not fetch single bytes: it loads a **cache line** (commonly 64 bytes) at a time. Reading memory in order uses every byte of each line; jumping around wastes most of it.\n\nThat is why one `std::vector<float>` holding a whole image beats a vector of vectors, and why the innermost loop should walk the **last** axis.'),
      mc('How would you speed up this loop over a row-major image?', ['Swap the loops so w is the inner loop', 'Use double instead of float', 'Make H smaller', 'Nothing: both orders cost the same'], 'Consecutive w values are neighbours in memory, so the cache is used fully.', 'for (int w = 0; w < W; ++w)\n    for (int h = 0; h < H; ++h)\n        sum += img[h * W + w];'),
      tf('A std::vector<std::vector<float>> stores all its rows in one contiguous block.', false, 'Each inner vector has its own allocation, so rows can be anywhere in memory.'),
      mc('A server has 8 cores. You run 4 inference sessions at once, each configured with 8 worker threads. What is the likely result?', ['Oversubscription: 32 threads compete for 8 cores and latency becomes unpredictable', 'Four times the speed of one session', 'Each session automatically gets exactly 2 cores', 'Nothing changes'], 'Keep the total number of busy threads close to the number of cores.'),
      match('Match the term', [['Memory-mapped file', 'The OS loads file pages into memory on demand'], ['Thread pool', 'Reusable workers instead of one new thread per task'], ['Dynamic axis', 'A dimension, such as batch size, left open at export'], ['Execution provider (ONNX Runtime)', 'A backend that runs the model’s operations, such as CPU or GPU']]),
      mc('Why can this call give wrong results?', ['A cropped cv::Mat is usually not contiguous, so .data does not point to a packed block', 'cv::Rect is not allowed here', 'run_model needs a const pointer', 'imread returns floats'], 'Rows of a sub-image are separated by the full image’s row length; clone() it to get a packed copy.', 'cv::Mat roi = img(cv::Rect(100, 50, 224, 224));\nrun_model(roi.data);   // expects 224 x 224 x 3 packed bytes')),

    L('C++ bugs and debugging',
      info('Two bugs that cost days', 'Deployment bugs are rarely clever, and the compiler often says nothing.\n\n- **Dangling pointers:** returning a pointer into a local `std::vector`. The vector is destroyed on return, so the pointer points at freed memory.\n- **Integer division:** `1 / 255` is `0` in C++, because both operands are `int`. Write `1.0f / 255`.'),
      type('What does 7 / 2 evaluate to in C++ when both numbers are int?', ['3'], 'Integer division drops the fraction.'),
      mc('What is wrong with this function?', ['It returns a pointer to memory that is freed when the function returns', 'fill cannot take a vector', 'data() is not allowed on a vector', 'Nothing: the vector lives on'], 'buf is destroyed at the closing brace; return the vector itself, or write into a caller-owned buffer.', 'const float* get_input() {\n    std::vector<float> buf(3 * 224 * 224);\n    fill(buf);\n    return buf.data();\n}'),
      mc('A model gives garbage and every preprocessed pixel prints as 0. Why?', ['1 / 255 is integer division and equals 0', 'convertTo cannot scale', 'CV_32F is a double', 'img is in BGR order'], 'Use 1.0 / 255.0 so the division happens in floating point.', 'img.convertTo(f, CV_32F, 1 / 255);'),
      info('Sizes, signs and sanitizers', '`size_t` is **unsigned**: `i >= 0` is always true for it, so a reverse loop never ends. A 32-bit `int` overflows past about 2.1 billion, and a 3 × 30000 × 30000 tensor has 2.7 billion elements: compute indices in `size_t`.\n\nLet the tools hunt for you. Build with `-fsanitize=address,undefined` to catch out-of-bounds access, use-after-free and undefined behaviour at run time.'),
      mc('Why does this loop never finish?', ['i is unsigned, so i >= 0 is always true and it wraps around', 'size() returns a float', 'process cannot take a reference', '--i is not allowed'], 'Loop with an index that can go negative, or use iterators or a different condition.', 'for (size_t i = v.size() - 1; i >= 0; --i) {\n    process(v[i]);\n}'),
      mc('Why can `int i = c * H * W + h * W + w;` be wrong for a huge tensor?', ['The int can overflow past about 2.1 billion, which is undefined behaviour', 'int cannot be negative', 'c is not allowed in an index', 'H and W must be const'], 'Use size_t or std::ptrdiff_t for indices.'),
      fillc('g++ -g -fsanitize=___,undefined main.cpp -o main', ['address', 'speed', 'release', 'null'], 'AddressSanitizer finds out-of-bounds and use-after-free errors.'),
      order('Order a sound response to a crash that only appears in release builds', ['Reproduce it with a saved input', 'Rebuild with -g and the sanitizers', 'Read the first reported error and its stack trace', 'Fix the root cause, not the symptom', 'Add a regression test with the same input'], 'Reproduce, instrument, read, fix, protect.'),
      mc('The debug build works, the release build gives different results, and there are no warnings. Most likely cause?', ['Undefined behaviour such as an uninitialised variable or an out-of-bounds read', 'The release build uses a different GPU', 'The CPU is slower in release', 'The optimiser is always wrong'], 'Optimisation exposes bugs the debug build hides; sanitizers find them.')),

    L('Case study: a 30 fps inspection camera',
      info('The brief', 'An inspection camera on a production line delivers **30 frames per second**. A Python prototype finds defects, but takes **90 ms** per frame: capture 5, preprocessing 35, inference 40, post-processing 10. The line cannot slow down.\n\nRebuilding a Python prototype as a C++ pipeline is a standard industrial-vision pattern. The numbers here are illustrative. You make the decisions.'),
      type('How many milliseconds per frame are available at 30 fps? Round down to a whole number.', ['33', '33.3', '33 ms'], '1000 / 30 = 33.3.'),
      mc('Which change do you make first?', ['Export to ONNX and run it with an optimised C++ runtime, because inference is the largest slice', 'Rewrite the capture code because it comes first', 'Lower the camera to 10 fps', 'Remove post-processing'], 'Inference is 40 of the 90 ms; preprocessing at 35 ms is next.'),
      mc('After the port the stages take 2 + 8 + 15 + 4 = 29 ms. A better model raises inference to 25 ms, so the total is 39 ms, but the line only needs 30 frames per second and 100 ms latency is acceptable. What is the best design?', ['Run the stages as a pipeline on separate threads with small bounded queues', 'Skip every other frame silently', 'Use unlimited queues so nothing is ever dropped', 'Reduce the camera resolution to nothing'], 'In a pipeline, throughput is set by the slowest stage, not the sum.'),
      type('In that pipeline the slowest stage takes 25 ms. What is the maximum frame rate?', ['40'], '1000 / 25 = 40 frames per second.'),
      info('Parity before speed', 'A fast pipeline that gives different answers is worthless. Before celebrating:\n\n1. Compare C++ outputs with Python on 100 saved frames.\n2. Check **geometry**: if the model input is letterboxed (resized with its aspect ratio kept and padded), box coordinates must be mapped back to the original image.\n3. Test the worst frames, not only typical ones.'),
      mc('Detected boxes are shifted and wrongly scaled only for 1280 × 720 images. The model input is a 640 × 640 letterboxed image. What is the likely bug?', ['The padding and scale were not undone when mapping boxes back', 'The model has too few layers', 'The queue is too short', 'The camera is out of focus'], 'Reverse the resize and padding when converting box coordinates.'),
      tf('If the average frame time is 20 ms, the 33 ms deadline is always met.', false, 'Averages hide the tail; look at the worst case and the 99th percentile.'),
      order('Order the rollout', ['Export the model and validate it against Python', 'Port preprocessing and prove tensor parity', 'Add timing around every stage', 'Pipeline the stages with bounded queues', 'Run an hour-long soak test and read p99 and dropped frames'], 'Correctness first, then speed, then a long test.'),
      mc('Which result do you use for sign-off?', ['p99 frame time under 33 ms and no dropped frames over a long soak test, with outputs matching Python', 'The best frame time seen', 'The average of the first ten frames', 'The model accuracy alone'], 'A real-time system must meet its deadline on every frame, including the slow ones.')),

    L('Interview drill: C++ for deployment',
      info('What interviewers probe', 'Deployment interviews mix C++ language questions with engineering judgement. Typical openings: ownership and the rule of zero, stack versus heap, copies versus moves, and "how would you make this faster?".\n\nThe follow-up is nearly always "what could go wrong?". Answer with a concrete bug you have seen or can imagine.'),
      mc('"What is the rule of zero?" Best answer?', ['Design classes so their members manage themselves (RAII), and write no custom destructor, copy or move', 'Never write a constructor', 'Always allocate with new', 'Use zero threads'], 'Let std::vector, std::unique_ptr and friends do the work.'),
      mc('Follow-up: one Buffer is copied into another. What goes wrong?', ['Both objects hold the same pointer and delete it: a double free', 'Nothing: copies are deep by default', 'The constructor leaks', 'delete[] is not allowed'], 'The compiler-generated copy copies the pointer. Follow the rule of three, five or zero.', 'class Buffer {\n    float* data_;\npublic:\n    Buffer(size_t n) : data_(new float[n]) {}\n    ~Buffer() { delete[] data_; }\n};'),
      mc('Where do the 1000 floats of `std::vector<float> v(1000)` live?', ['On the heap, although the vector object itself may be on the stack', 'On the stack', 'In flash', 'On the GPU'], 'The vector holds a pointer to heap storage.'),
      order('Order a strong answer to "How would you halve the latency of this C++ pipeline?"', ['Measure and split time across the stages', 'Fix the largest slice first', 'Remove copies and per-frame allocations', 'Use an optimised runtime, lower precision or threads where measured to help', 'Re-measure and re-check accuracy'], 'Measure, fix the biggest cost, verify.'),
      info('Follow-ups to expect', '- "Why `const&` instead of by value?" Avoids a copy for large objects.\n- "When would you use `shared_ptr`?" Truly shared ownership, and you accept the reference-count cost.\n- "What happens if a destructor throws?" Usually the program terminates; destructors should not throw.\n- "How do you test this?" Unit tests, back-to-back tests against Python, sanitizers in CI.'),
      tf('Passing a std::vector by value to a function copies it unless it is moved.', true, 'Pass by const reference to avoid the copy, or std::move it in if the function takes ownership.'),
      match('Match the concept to a one-line answer', [['Virtual destructor', 'Deleting a derived object through a base pointer works correctly'], ['noexcept move', 'Lets containers move instead of copy when they grow'], ['std::span', 'A non-owning view of contiguous memory'], ['RAII', 'A resource is released when its owner leaves scope']]),
      mc('Your class has a move constructor, yet std::vector copies the elements when it grows. Why?', ['The move constructor is not marked noexcept', 'vector never moves', 'The class is too small', 'Moves only work on the GPU'], 'vector moves on reallocation only if the move cannot throw; otherwise it copies to keep its guarantee.'),
      mc('"Tell me about a hard bug." Which answer structure is strongest?', ['Symptom, how you isolated it, the root cause, the fix, and how you prevented a repeat', 'It was hard and I fixed it', 'A list of tools you know', 'Blame the compiler'], 'Interviewers want to see your method, not only the outcome.'))
  ],

  'cuda-gpu': [
    L('CPU versus GPU',
      info('Many simple workers', 'A CPU has a few powerful cores: great at complicated, branching work.\n\nA GPU has **thousands** of simple cores: great at doing the same simple operation on huge arrays at once.\n\nNeural networks are mostly matrix multiplications, which are exactly that.'),
      mc('Which task suits a GPU best?', ['Multiplying two large matrices', 'Parsing a config file', 'Running a web server loop', 'Walking a linked list'], 'It is the same operation on many elements, with no dependencies between them.'),
      match('Match the term', [['Host', 'The CPU and its memory'], ['Device', 'The GPU and its memory'], ['Kernel', 'A function that runs on the GPU'], ['VRAM', 'Memory on the graphics card']]),
      tf('The CPU and the GPU share the same memory on a typical desktop.', false, 'They are separate; data must be copied across.'),
      fillc('x = x.to("___")   # move a PyTorch tensor to the GPU', ['cuda', 'gpu0', 'fast', 'vram'], 'The model and its inputs must be on the same device.'),
      mc('What error do you get if the model is on the GPU and the input is on the CPU?', ['A device mismatch error', 'Silent wrong results', 'Automatic copy', 'Out of memory'], 'PyTorch refuses to mix devices.'),
      mc('Which tool shows GPU utilisation and memory?', ['nvidia-smi', 'top', 'ping', 'git status'], 'Use it first when something is slow or out of memory.')),

    L('Threads, blocks and grids',
      info('How a kernel runs', 'When you launch a kernel, the GPU runs it in many **threads** at once. Threads are grouped into **blocks**, and blocks into a **grid**.\n\nEach thread asks "which one am I?" and works on its own element:\n\n```cpp\nint i = blockIdx.x * blockDim.x + threadIdx.x;\n```'),
      type('blockDim = 256. Thread 10 of block 2 works on which global index?', ['522'], '2 * 256 + 10.'),
      type('You have 1000 elements and 256 threads per block. How many blocks do you need?', ['4'], 'ceil(1000 / 256) = 4, giving 1024 threads.'),
      mc('4 blocks of 256 threads is 1024 threads, but there are only 1000 elements. What must the kernel do?', ['Check `if (i < n)` before touching memory', 'Nothing, the GPU handles it', 'Launch 3 blocks instead', 'Pad the array on the CPU every time'], 'Extra threads must do nothing or they write out of bounds.'),
      order('Order the lines of a vector-add kernel', ['__global__ void add(const float* a, const float* b, float* c, int n) {', '    int i = blockIdx.x * blockDim.x + threadIdx.x;', '    if (i < n)', '        c[i] = a[i] + b[i];', '}'], 'Index, bounds check, work.'),
      fillc('int blocks = (n + threads - 1) ___ threads;   // round up', ['/', '%', '*', '-'], 'Integer ceiling division.'),
      order('Order what a CUDA program does', ['Allocate memory on the device', 'Copy input from host to device', 'Launch the kernel', 'Copy the result back to the host', 'Free device memory'], 'Minimise the copies: they are slow.'),
      tf('Most deep learning engineers write CUDA kernels every day.', false, 'Libraries such as cuDNN and PyTorch provide them. You need the concepts to use them well.')),

    L('Making training fast',
      info('Where the time goes', 'A training step is: load data (CPU) → copy to GPU → forward and backward (GPU) → update.\n\nIf the GPU waits for data, it sits idle. **Low GPU utilisation usually means a CPU-side bottleneck.**'),
      mc('GPU utilisation is 25% during training. First thing to try?', ['More data-loader workers and faster preprocessing', 'A bigger model', 'A lower learning rate', 'More epochs'], 'Feed the GPU faster.'),
      fillc('loader = DataLoader(ds, batch_size=64, num_workers=8, ___=True)', ['pin_memory', 'gpu_memory', 'fast_copy', 'cuda_only'], 'Pinned (page-locked) host memory makes copies to the GPU faster.'),
      info('GPU calls are asynchronous', 'When Python calls a GPU operation it returns **immediately**; the work is queued.\n\nSo timing with a stopwatch around one call measures almost nothing. Synchronise first, and warm up before measuring.'),
      fillc('torch.cuda.___()   # wait for queued GPU work before reading the clock', ['synchronize', 'flush', 'wait_all', 'block'], 'Otherwise you time the queueing, not the work.'),
      mc('Which line inside a training loop quietly slows it down?', ['loss_history.append(loss.item()) on every step', 'optimizer.step()', 'loss.backward()', 'optimizer.zero_grad()'], '.item() forces a GPU-to-CPU copy and a synchronisation each time. Do it every N steps.'),
      mc('What does mixed precision (FP16) give you?', ['About half the memory and faster maths', 'Double the accuracy', 'Larger weights', 'No need for a GPU'], 'Use automatic mixed precision with a gradient scaler.'),
      mc('"CUDA out of memory". Which helps without changing the effective batch size?', ['Smaller batch with gradient accumulation', 'More epochs', 'A higher learning rate', 'More data-loader workers'], 'Accumulate gradients over several small batches, then step.')),

    L('Inference and interview level',
      info('Throughput versus latency', '**Latency** is the time for one request. **Throughput** is requests per second.\n\nBatching raises throughput because the GPU does more work per launch, but each request may wait for the batch to fill, so latency rises. Choose by the product requirement.'),
      mc('A real-time camera pipeline needs each frame in under 30 ms. Preferred setting?', ['Batch size 1, optimised engine', 'Batch size 256', 'Run on CPU only', 'Process every tenth second'], 'Latency is the constraint, so do not wait to fill batches.'),
      mc('What does TensorRT do to a model?', ['Compiles it for one GPU: fuses layers, picks kernels, applies FP16 or INT8', 'Retrains it', 'Converts it to Python', 'Encrypts the weights'], 'The resulting engine is specific to the GPU and software version.'),
      tf('A TensorRT engine built on one GPU model is guaranteed to be optimal on any other GPU.', false, 'Engines are built for a specific device; rebuild on the target.'),
      info("Amdahl's law", 'If a fraction `p` of the run time is sped up `n` times:\n\n```\nspeedup = 1 / ((1 - p) + p / n)\n```\n\nThe part you did **not** accelerate sets the ceiling.'),
      type('Preprocessing on the CPU takes 50% of the time. Even with an infinitely fast GPU, what is the maximum total speed-up? (a number)', ['2', '2x', '2.0'], '1 / (1 - 0.5) = 2.'),
      mc('Inference is slow and the profiler shows 70% of time in image resize on the CPU. Best action?', ['Move or speed up preprocessing, for example GPU-side resize', 'Buy a bigger GPU', 'Quantise the model', 'Increase the batch size'], 'Attack the largest slice first.'),
      order('Order a sound GPU performance investigation', ['Warm up and synchronise so measurements are valid', 'Profile to split time across load, transfer, inference, postprocess', 'Fix the largest bottleneck', 'Measure again'], 'Measure, change one thing, measure.'),
      mc('Why can host-to-device copies dominate a small model’s latency?', ['The transfer cost is fixed and large compared with tiny compute', 'Small models use more VRAM', 'GPUs are slower at small maths', 'Copies are encrypted'], 'For tiny models the CPU can even be faster overall.')),

    L('Warps, memory levels and synchronisation',
      info('Warps and divergence', 'The GPU does not run threads one by one. On NVIDIA GPUs, threads execute in groups of **32** called **warps**, all following the same instruction at the same time.\n\nIf threads of one warp take different sides of an `if`, the hardware runs one side, then the other, with the rest of the threads idle. This is **divergence**, and it wastes time.'),
      type('A block has 256 threads. How many warps is that on an NVIDIA GPU?', ['8'], '256 / 32 = 8.'),
      mc('Which condition causes divergence inside a warp?', ['if (threadIdx.x % 2 == 0)', 'if (blockIdx.x % 2 == 0)', 'if (n > 0), where n is a kernel argument', 'No condition ever does'], 'Neighbouring threads of one warp take different paths. A block-level condition sends the whole warp the same way.'),
      info('Memory levels', 'Fast memory is small, large memory is slow:\n\n- **Registers:** private to one thread, fastest.\n- **Shared memory:** on the chip, shared by the threads of **one block**, managed by your code.\n- **Global memory:** large, visible to all threads and to the host copies, slowest of the three.\n\nWhen neighbouring threads read neighbouring addresses, the hardware **coalesces** those reads into few memory transactions.'),
      mc('Which access pattern is better for a kernel where thread i reads one float?', ['a[i]', 'a[i * 32]', 'a[random()]', 'They are all the same'], 'Neighbouring threads touching neighbouring addresses can be coalesced.'),
      match('Match the term', [['Registers', 'Private to one thread, fastest'], ['Shared memory', 'Shared by the threads of one block'], ['Global memory', 'Large, visible to all threads, slowest of the three'], ['__syncthreads()', 'All threads of a block wait for each other']]),
      tf('Threads in different blocks can synchronise with __syncthreads().', false, 'It only synchronises the threads of one block.'),
      mc('Why would a kernel copy a tile of data into shared memory first?', ['Many threads reuse the same values, and shared memory is much faster than repeated global reads', 'Shared memory is larger than global memory', 'It is the only way to read memory', 'It removes the need for threads'], 'Tiled matrix multiplication is the classic example.'),
      mc('A kernel is launched with 1 block of 256 threads on a big GPU. Why is that a poor use of it?', ['Blocks are spread across the GPU’s multiprocessors, and one block keeps most of them idle', 'A block may not have 256 threads', 'GPUs cannot run one block', 'Kernels need at least 1000 blocks to compile'], 'Launch enough blocks to occupy the whole device.')),

    L('GPU bugs and debugging',
      info('Errors you do not see', 'CUDA calls report problems through **return codes**, and kernel launches are **asynchronous**: a bad launch may only show up at a later call that has nothing to do with it.\n\nWrap every call in a check, and check the launch itself:\n\n```cpp\n#define CHECK(call) do { cudaError_t e = (call); \\\n    if (e != cudaSuccess) { fprintf(stderr, "%s\\n", cudaGetErrorString(e)); exit(1); } } while (0)\n```'),
      mc('This kernel is launched with 4 blocks of 256 threads for n = 1000. What is the bug?', ['No bounds check: threads 1000 to 1023 write outside the array', 'x must be a const pointer', 'The kernel needs a return value', 'blockDim cannot be used in a kernel'], 'Add `if (i < n)` before touching memory.', '__global__ void scale(float* x, float s, int n) {\n    int i = blockIdx.x * blockDim.x + threadIdx.x;\n    x[i] *= s;\n}'),
      mc('With n = 1000 and 256 threads per block, the host computes `int blocks = n / 256;`. What happens?', ['Only 3 blocks launch, so the last elements are never processed', 'It launches exactly the right number', '5 blocks launch', 'The launch fails with a compile error'], 'Integer division rounds down; use (n + 255) / 256.'),
      type('With 3 blocks of 256 threads, how many of the 1000 elements are never processed?', ['232'], '3 × 256 = 768, and 1000 - 768 = 232.'),
      mc('What goes wrong here, with n = 1000 floats?', ['Only the first 250 floats are copied, because the size is in bytes', 'The copy direction is wrong', 'd_x must be freed first', 'cudaMemcpy cannot copy floats'], 'Use n * sizeof(float).', 'cudaMemcpy(d_x, h_x, n, cudaMemcpyHostToDevice);'),
      info('Async surprises and memory growth', 'Because launches return at once, an error such as "illegal memory access" can be **reported by a later call**, for example a cudaMemcpy ten lines further down.\n\nTo find the real culprit, check the error right after each launch with `cudaGetLastError()`, and synchronise while debugging.\n\nIn PyTorch, memory grows when you keep tensors that still carry their autograd graph, for example by appending outputs during evaluation.'),
      fillc('add<<<blocks, threads>>>(a, b, c, n);\nCHECK(cudaGet___Error());', ['Last', 'First', 'Any', 'Next'], 'cudaGetLastError returns the error from the most recent launch.'),
      mc('Evaluation runs out of GPU memory after a few hundred batches. What is the likely cause?', ['Each output keeps its autograd graph alive: wrap evaluation in torch.no_grad() and move results off the GPU', 'The loader is too slow', 'The model has too few parameters', 'Python lists are not allowed'], 'Gradients are not needed for evaluation, so do not record them.', 'outputs = []\nfor x in loader:\n    outputs.append(model(x))'),
      order('Order a sound response to an "illegal memory access" error', ['Make it reproducible with a small fixed input', 'Add CHECK after every CUDA call and after each launch', 'Run a memory checker such as compute-sanitizer', 'Find the failing kernel and check its indices and bounds', 'Fix it and re-run the same input'], 'Reproduce, instrument, locate, fix, re-test.'),
      mc('The error is reported at a cudaMemcpy line that has nothing to do with your kernel. Why?', ['The kernel ran asynchronously, so its error appeared at the next call that synchronised', 'cudaMemcpy is broken', 'The error is random', 'The compiler moved the kernel'], 'Check the launch with cudaGetLastError and synchronise while debugging.')),

    L('Case study: batching for a photo service',
      info('The brief', 'A photo-tagging service runs an image classifier on one GPU. Requests arrive one by one, about **250 per second**. At batch size 1 one request takes **10 ms** on the GPU. A batch of 8 takes **24 ms**.\n\nDynamic batching in inference servers is a widely used way to raise throughput. These timings are illustrative; you make the decisions.'),
      type('At batch size 1, how many requests per second can the GPU handle at most?', ['100'], '1000 ms / 10 ms = 100.'),
      mc('Requests arrive at 250 per second, but only 100 per second can be served. The queue grows without limit. Best first move?', ['Dynamic batching: wait a few milliseconds and run several requests together', 'Raise the client timeouts', 'Restart the server every hour', 'Switch the model to FP64'], 'Batching gives the GPU more work per launch.'),
      info('How dynamic batching works', 'The server collects requests until the batch is **full** or a **maximum wait** expires, whichever comes first.\n\nTwo knobs: the maximum batch size (limited by memory and the best throughput) and the maximum wait (limited by your latency target). A longer wait means bigger batches but slower answers.'),
      type('A batch of 8 takes 24 ms. How many requests per second is that? Round down.', ['333'], '8 / 0.024 = 333.3.'),
      mc('The latency target is 50 ms. Compute takes 24 ms and other steps about 10 ms. Which maximum wait is sensible?', ['About 5 ms', '40 ms', '200 ms', 'No limit: wait until the batch is full'], '5 + 24 + 10 = 39 ms stays inside 50 ms; a long wait would break the target.'),
      mc('After batching the GPU is busy, but the 4 CPU cores decoding and resizing JPEGs sit at 100%. What next?', ['Add more preprocessing workers, or move decoding and resizing to the GPU', 'Add a larger batch size', 'Lower the model accuracy', 'Disable batching'], 'Now the CPU is the bottleneck, so attack it.'),
      tf('Switching the model to FP16 for speed means you must re-check accuracy on a validation set.', true, 'Reduced precision can change outputs slightly.'),
      order('Order the rollout', ['Measure the baseline latency and throughput', 'Enable dynamic batching with a small maximum wait', 'Load-test at the expected peak', 'Tune batch size and wait', 'Canary in production and watch p50, p99 and GPU use'], 'Measure, change, test, tune, release gradually.'),
      mc('In the load test p99 latency is high only when traffic is low. Why?', ['With few requests, batches never fill and every request waits the full maximum wait', 'The GPU is faster at low traffic', 'The queue is too long', 'Batching breaks at low traffic'], 'Lower the maximum wait, or allow small batches to run early.')),

    L('Interview drill: GPUs and CUDA',
      info('What interviewers probe', 'GPU interviews check **mental models**, not syntax: why a GPU wins, where time goes, and how you would find a bottleneck.\n\nExpect "why is it slow?" and "why does it run out of memory?". A strong answer names a measurement, a likely cause and a fix.'),
      mc('"Why is a GPU not always faster than a CPU?" Strongest answer?', ['Small or branchy work cannot fill the GPU, and copies between host and device add overhead', 'GPUs are slower per core, so they never win', 'GPUs cannot run Python', 'CPUs have more cores'], 'The GPU wins on large, regular, data-parallel work.'),
      mc('You run this code and get a device mismatch error. Why?', ['x.to("cuda") returns a new tensor that was not assigned, so x is still on the CPU', 'model.to("cuda") does nothing', 'randn cannot run on the GPU', 'The model needs a batch dimension'], 'Module.to moves the model in place; Tensor.to returns a copy, so write x = x.to("cuda").', 'model = Net()\nx = torch.randn(1, 3, 224, 224)\nx.to("cuda")\nmodel.to("cuda")\ny = model(x)'),
      order('Order a strong answer to "Training is slow. What do you do?"', ['Check GPU utilisation and profile one step', 'Fix the input pipeline if the GPU waits for data', 'Enable mixed precision', 'Raise the batch size as far as memory allows', 'Consider more GPUs only after that'], 'Cheap measured fixes first, scale-out last.'),
      info('Follow-ups to expect', '- "What is a CUDA stream?" An ordered queue of GPU work; work in different streams may overlap.\n- "Why do results differ between CPU and GPU?" Floating-point addition is not associative, and the order of operations differs.\n- "How do you measure GPU time?" Warm up, synchronise, then time.\n- "What limits batch size?" Memory for weights, activations and gradients.'),
      mc('What does a CUDA stream give you?', ['An ordered queue of GPU operations, where different streams may overlap, for example a copy with a kernel', 'A faster clock', 'More VRAM', 'A way to run Python on the GPU'], 'Streams let transfers and compute overlap.'),
      type('How many threads form a warp on NVIDIA GPUs?', ['32'], 'A warp is 32 threads.'),
      match('Match the symptom to the likely cause', [['GPU idle between steps', 'The input pipeline starves it'], ['First iteration much slower', 'Warm-up and initialisation'], ['Out of memory after many batches', 'Tensors kept alive, often with their graph'], ['Slightly different results on CPU and GPU', 'Different order of floating-point operations']]),
      mc('Why does FP16 training use a loss scaler?', ['Small gradients can underflow to zero in FP16, and scaling the loss keeps them representable', 'FP16 cannot store weights', 'It makes the GPU hotter', 'It replaces the optimiser'], 'The gradients are unscaled again before the update.'),
      tf('Floating-point results on a GPU can differ slightly between runs or devices.', true, 'The order of parallel additions can change, and so can the last digits.'))
  ],

  'ecu-deploy': [
    L('What is an ECU?',
      info('Computers in a car', 'A modern car has dozens of **ECUs** (electronic control units): small embedded computers for brakes, engine, airbags, windows, radar, cameras.\n\nMost use a **microcontroller**: a single chip with a CPU, a little RAM and flash memory. They are cheap, robust and very limited.'),
      match('Match the memory to its role', [['Flash', 'Program code and constants; kept without power'], ['RAM', 'Working data; lost without power'], ['Stack', 'Local variables and call frames'], ['EEPROM / data flash', 'Settings saved between drives']]),
      mc('A typical small ECU microcontroller has RAM in the order of…', ['Kilobytes to a few megabytes', 'Tens of gigabytes', 'Terabytes', 'It has no RAM'], 'Which is why model size matters so much.'),
      info('Hard real time', 'An ECU task runs on a fixed cycle, for example every 10 ms. If it finishes late, the system has failed, even if the answer is correct.\n\nSo engineers care about **worst-case execution time (WCET)**, not the average.'),
      mc('A task runs every 10 ms. Its average run time is 3 ms and its worst case is 12 ms. Is that acceptable?', ['No: the worst case misses the deadline', 'Yes: the average is fine', 'Yes: it only happens sometimes', 'It depends on the colour of the car'], 'Deadlines must hold every cycle.'),
      tf('Dynamic memory allocation (malloc) is normally avoided in safety-related ECU code.', true, 'It can fragment, fail and take unpredictable time.'),
      mc('Which sensor ECU would most plausibly run a small ML classifier?', ['A radar detecting whether its cover is blocked', 'A window switch', 'A fuse', 'A battery cable'], 'Simple models on sensor ECUs are common: blockage, classification, diagnostics.')),

    L('Talking on the bus',
      info('CAN in one minute', 'ECUs exchange short messages on the **CAN bus**. A classic frame carries an ID and up to **8 data bytes**.\n\nInside those bytes, **signals** are packed as groups of bits. A database file (DBC) says for each signal: start bit, length, scale, offset.\n\n```\nphysical = raw * scale + offset\n```'),
      type('A temperature signal has raw = 100, scale = 0.5, offset = -40. What is the physical value?', ['10', '10.0'], '100 * 0.5 - 40 = 10.'),
      type('A vehicle speed is sent as a 16-bit raw value with scale 0.01 km/h. What raw value means 100 km/h?', ['10000'], '100 / 0.01.'),
      mc('Why use scale and offset instead of sending floats?', ['Integers are compact and need no floating-point support', 'Floats are illegal on CAN', 'It hides the data', 'It is faster to type'], 'An 8-bit raw value can carry -40 to 87.5 °C in 0.5 steps.'),
      fillc('raw = (value >> start_bit) & ((1 << ___) - 1)', ['length', 'offset', 'scale', '8'], 'Shift down to the signal, then mask its width.'),
      mc('An 8-bit signed signal has raw bits 0xFF. Its value is…', ['-1', '255', '127', '-128'], 'Two’s complement: the top bit is set, so subtract 256.'),
      match('Match the network to its use', [['CAN', 'Robust control messages, up to 1 Mbit/s'], ['CAN FD', 'Larger frames (64 bytes), higher speed'], ['Automotive Ethernet', 'Cameras, radar data, service communication'], ['LIN', 'Cheap low-speed links for simple parts']]),
      tf('Raw camera video is normally sent over classic CAN.', false, 'Far too much data. Cameras use serial video links or Ethernet.')),

    L('AUTOSAR, tests and standards',
      info('Two platforms', '**AUTOSAR Classic** runs on microcontrollers: everything is configured statically, tasks are scheduled by a small real-time OS.\n\n**AUTOSAR Adaptive** runs on powerful processors with a POSIX OS (Linux, QNX): services can be started and updated dynamically. Perception networks live here.'),
      mc('Where would a large camera perception network run?', ['On an Adaptive-class high-performance computer', 'On an 8-bit microcontroller', 'On the CAN transceiver', 'In the DBC file'], 'It needs gigabytes of memory and an accelerator.'),
      mc('In AUTOSAR Classic, application code is organised into…', ['Software components with runnables', 'Docker containers', 'Python modules', 'Web services'], 'The RTE connects components; the OS schedules runnables.'),
      order('Order the test levels from earliest to closest to the vehicle', ['MIL: model in the loop', 'SIL: software in the loop', 'PIL: processor in the loop', 'HIL: hardware in the loop', 'Vehicle test'], 'Each step replaces something simulated with the real thing.'),
      match('Match the standard to its subject', [['MISRA C', 'Coding rules'], ['ASPICE', 'Development process and traceability'], ['ISO 26262', 'Functional safety (ASIL)'], ['ISO 21448 SOTIF', 'Safety of intended functionality'], ['ISO/SAE 21434', 'Cybersecurity']]),
      mc('Which ASIL is the most demanding?', ['ASIL D', 'ASIL A', 'ASIL B', 'QM'], 'D is highest; QM means no safety requirement.'),
      mc('An ML model misclassifies in heavy rain although the code has no bug. Which standard addresses this kind of risk?', ['ISO 21448 (SOTIF)', 'MISRA C', 'ISO 9001 only', 'The DBC format'], 'SOTIF covers hazards from performance limits, not from faults.'),
      tf('Traceability means every requirement can be linked to its design, code and tests.', true, 'It is a core ASPICE expectation.')),

    L('Putting a model on an ECU',
      info('The pipeline', '1. **Fit the budget:** small model, quantised or fixed point.\n2. **Convert to C** that follows the coding standard.\n3. **Back-to-back test** against the Python reference.\n4. **Integrate** as a software component with defined inputs, outputs and cycle time.\n5. **Measure** WCET, stack and memory on the target.\n6. **Protect:** plausibility checks, output monitoring, safe state.'),
      mc('What is a back-to-back test?', ['The same inputs through the reference model and the embedded code, outputs compared', 'Two ECUs wired together', 'Testing the rear sensors', 'Running tests twice'], 'It proves the conversion did not change behaviour.'),
      mc('Your random forest has 500 deep trees and does not fit in flash. Reasonable options?', ['Fewer or shallower trees, shared thresholds, quantised leaf values', 'Add more RAM by software', 'Use recursion', 'Store it on CAN'], 'Trade a little accuracy for size, and measure both.'),
      fillc('if (count == SIZE) {\n    total -= buf[head];\n}\nbuf[head] = x;\ntotal += x;\nhead = (head + 1) ___ SIZE;', ['%', '/', '*', '&&'], 'A ring buffer wraps the index: constant memory, constant time.'),
      mc('Why keep a running sum in a moving-average filter on an ECU?', ['Each update is O(1) instead of summing the whole window', 'It is more accurate', 'It uses no RAM', 'MISRA requires sums'], 'Predictable, minimal execution time per cycle.'),
      info('When the model is wrong', 'A safety function cannot blindly trust a model. Typical protections:\n\n- **input plausibility:** is the sensor data in range and fresh?\n- **output monitoring:** is the result physically possible?\n- **debouncing:** require a condition to hold for several cycles\n- **safe state:** what the function does when confidence is lost'),
      mc('A blockage classifier flickers between "blocked" and "clear" on every cycle. Standard fix?', ['Debounce: require N consecutive cycles before changing state', 'Run it less often', 'Remove the classifier', 'Increase the CAN speed'], 'Hysteresis or counters prevent toggling outputs.'),
      mc('Where do you measure worst-case execution time for the final evidence?', ['On the target hardware', 'On your laptop', 'In the notebook', 'It cannot be measured'], 'PC timing says little about a microcontroller.'),
      order('Order a strong interview answer on ECU deployment', ['State the constraints: memory, cycle time, safety level', 'Shrink the model and convert it to compliant C', 'Verify back to back, then SIL, PIL and HIL', 'Measure on target and add monitoring and a safe state'], 'Constraints, conversion, verification, protection.')),

    L('Bus priority, CPU load and message protection',
      info('Who talks first: arbitration', 'Several ECUs may try to send at the same moment. On CAN, each frame has an **ID**, and the **lowest ID wins** the bus without any frame being destroyed. The loser simply waits and tries again.\n\nSo the ID is also a priority: safety-critical messages get low IDs.'),
      mc('ECU A sends a frame with ID 0x100 and ECU B sends ID 0x200 at the same instant. Which frame goes first?', ['0x100', '0x200', 'Both are lost', 'The longer one'], 'The lower ID has the higher priority.'),
      type('A CPU runs three cyclic tasks: 2 ms every 10 ms, 5 ms every 20 ms and 1 ms every 5 ms. What is the CPU utilisation in percent?', ['65', '65%'], '2/10 + 5/20 + 1/5 = 0.2 + 0.25 + 0.2 = 0.65.'),
      info('Priorities and byte order', 'With a fixed-priority scheduler, a common rule is **rate-monotonic**: the task with the **shortest period** gets the highest priority. Utilisation must stay below 100%, and real projects keep a safety margin.\n\nCAN signals can be **little-endian** (Intel) or **big-endian** (Motorola) in a DBC. With big-endian the first byte is the most significant: bytes `0x12 0x34` mean `0x1234`.'),
      mc('Under rate-monotonic scheduling, which task gets the highest priority?', ['The task with the shortest period', 'The task with the longest run time', 'The task written first', 'The task with the largest memory use'], 'Frequent tasks have the tightest deadlines.'),
      type('Two bytes 0x12 0x34 are read as a big-endian 16-bit unsigned value. What is the decimal value?', ['4660'], '0x1234 = 4 × 1 + 3 × 16 + 2 × 256 + 1 × 4096 = 4660.'),
      match('Match the protection mechanism', [['Alive counter', 'Increments every message so a frozen or repeated frame is detected'], ['CRC', 'Checksum that detects corrupted data'], ['Timeout monitoring', 'Detects that an expected message did not arrive'], ['Arbitration', 'Decides which frame wins the bus']]),
      mc('A receiver gets correct speed values, but the alive counter has not changed for 5 cycles. What does this suggest?', ['The sender froze and keeps repeating its last frame, so the data should be treated as invalid', 'Everything is fine', 'The CRC is wrong on the bus', 'The bus is at full load'], 'A healthy sender increments the counter every message.'),
      tf('A CRC in the message payload is redundant because the CAN hardware already has a CRC.', false, 'End-to-end protection also covers the software path, sender and receiver.'),
      mc('A 10 ms task uses 7 ms worst case. A new model adds 4 ms worst case. What is the right conclusion?', ['11 ms exceeds the 10 ms deadline: shrink or optimise the model, or restructure the tasks', 'Fine: the average is lower', 'Fine: add 1 ms of margin', 'Increase the CAN speed'], 'The deadline has to hold even in the worst case.')),

    L('ECU bugs and debugging',
      info('Signs and sizes', 'A 12-bit signed signal is read into a 16-bit variable. The bits are right, but the **sign is not extended**: 12-bit `0xFFF` (-1) becomes 4095.\n\nTo sign-extend a 12-bit value, check bit 11 (`0x800`) and, if set, fill the upper four bits with ones (`0xF000`). Always check every signed signal with a negative test vector.'),
      mc('What value does `value` hold when the 12 signal bits are all ones?', ['4095', '-1', '0', '-4095'], 'The raw value is 0xFFF; assigning it to int16_t does not sign-extend a 12-bit field.', 'uint16_t raw = (uint16_t)(((data[1] & 0x0F) << 8) | data[0]);\nint16_t value = raw;   /* 12-bit signed signal */'),
      type('A 12-bit two’s-complement raw value is 0x800. What is its decimal value?', ['-2048'], 'The top bit is set and the rest are zero: the most negative value, -2048.'),
      fillc('if (raw & 0x800u) {\n    raw |= ___;\n}\nint16_t value = (int16_t)raw;', ['0xF000u', '0x0FFFu', '0x00FFu', '0x0800u'], 'Setting the upper four bits extends the sign to 16 bits.'),
      info('Time and stack bugs', '**Timer wrap-around:** a 16-bit millisecond counter wraps at 65536. Code such as `now > deadline` breaks near the wrap. The safe pattern is `(uint16_t)(now - start) >= timeout`.\n\n**Stack overflow:** a big local array on a task with a small stack corrupts neighbouring memory without any error message. Put large buffers in static memory and check the stack high-water mark.'),
      type('A uint16_t timer holds 65500. After adding 100, what value does it hold?', ['64'], '65600 - 65536 = 64.'),
      mc('With now = 65500, `uint16_t deadline = now + 100;` and the test `if (now > deadline)` fires. What happens?', ['The timeout fires immediately, because deadline wrapped to 64', 'It fires after 100 ms as intended', 'It never fires', 'The compiler rejects it'], 'Compare elapsed time: (uint16_t)(now - start) >= 100.'),
      mc('A task with an 8 KB stack contains `float window[4096];` as a local variable. What is the risk?', ['The array needs 16384 bytes, so the stack overflows and corrupts memory', 'floats cannot be arrays', 'The compiler will always warn and stop', 'Nothing: arrays live in flash'], '4096 × 4 bytes = 16 KB. Make it static or shrink it.'),
      order('Order a response to "the ECU resets now and then in the field"', ['Read the reset reason and fault memory', 'Reproduce with the logged inputs on a bench or HIL rig', 'Check stack high-water marks and watchdog timing', 'Fix the root cause', 'Re-run the regression and back-to-back tests'], 'Evidence first, then reproduce, then fix.'),
      mc('Back-to-back tests pass in SIL on a PC but differ by 1 LSB on the target for some inputs. Likely cause?', ['int has 16 bits on the target, so an intermediate calculation overflows or is promoted differently', 'The PC is more accurate', 'The test vectors are too short', 'The target has no RAM'], 'Use fixed-width types such as int32_t so both platforms compute the same.')),

    L('Case study: radar blockage detection',
      info('The brief', 'A radar ECU must flag **blockage** (mud, snow, ice on the cover), so that driver-assistance functions can warn or switch off. Each 50 ms cycle it gets a few features, such as received power and number of detections.\n\nBudget: **20 KB** of flash for the model and **1 ms** worst case. Radar blockage detection is a typical sensor-ECU use of a small model. You make the decisions.'),
      mc('Which model type fits the budget best?', ['A small tree ensemble: tiny, fast and with a fixed worst-case time', 'A large CNN on raw radar data', 'A transformer', 'An LLM'], 'A few features and a hard budget call for a small, analysable model.'),
      type('The ensemble has 50 trees of depth 4. Each tree has at most 16 leaves, and each leaf is a 4-byte float. At most how many bytes do the leaf values need?', ['3200'], '50 × 16 × 4 = 3200 bytes.'),
      info('Raw outputs flicker', 'Sensors are noisy, so the classifier may flip between "blocked" and "clear". Real systems **debounce**: a state change needs the new condition for several consecutive cycles.\n\nThey also add a **plausibility check** on inputs and define a **safe state**: what the function reports when it is unsure.'),
      type('A cycle lasts 50 ms. You require 20 consecutive "blocked" cycles before declaring blockage. How long is that, in ms?', ['1000'], '20 × 50 ms = 1000 ms.'),
      mc('Which error is more dangerous?', ['Saying "clear" when the sensor is blocked', 'Saying "blocked" when it is clear', 'Both are equally harmless', 'Neither can happen'], 'A false clear lets a function rely on a blind sensor; a false blocked only reduces availability.'),
      order('Order the verification path', ['Generate the C code from the trained trees', 'Run a back-to-back test against Python on recorded features', 'Replay recorded drives in SIL', 'Measure WCET and memory on the target processor', 'Test on HIL with fault injection, then in cold-weather vehicle tests'], 'Each step moves closer to the real car.'),
      tf('Because the classifier only informs other functions, it needs no safety analysis.', false, 'Its errors can lead to hazards, so the required rigour follows from the function’s safety goals.'),
      mc('On the logged drives the longest run takes 0.4 ms against a 1 ms budget. Are you finished?', ['No: also test the worst-case path through every tree and the effect of interrupts, on the target', 'Yes: 0.4 is below 1', 'Yes: averages are enough', 'No: only the average matters'], 'WCET needs worst-case paths, not typical logs.'),
      mc('In heavy rain the field data shows more false "blocked" reports. What is the right response?', ['Add such data to the training set, retrain, and re-verify through the normal change process', 'Edit a threshold in the field and hope', 'Disable the function', 'Ignore it'], 'Changes to a safety-related function stay traceable and verified.')),

    L('Interview drill: ECU deployment',
      info('What interviewers probe', 'Automotive interviews test **discipline** as much as knowledge: do you think about timing, safety, traceability and verification?\n\nExpect questions on worst-case execution time, coding rules, testing levels and what happens when things fail. Follow-ups usually ask "how do you prove it?".'),
      mc('"What is WCET, and how do you obtain it?" Strongest answer?', ['The longest time a task can take; measured or analysed on the target with worst-case paths and interrupts, plus a margin', 'The average run time on a PC', 'The time of the first run', 'The clock frequency'], 'Deadlines are met only if the worst case fits.'),
      mc('Follow-up: why mark a hardware register or an ISR-shared variable `volatile`?', ['It tells the compiler the value can change outside normal program flow, so reads must not be optimised away', 'It makes the variable faster', 'It moves it to flash', 'It makes it thread-safe'], 'volatile prevents caching in a register, but it does not provide atomicity.'),
      order('Order a response to "the ECU output differs from Python by 1 LSB"', ['Reproduce with the exact input vector', 'Compare intermediate values stage by stage', 'Find the first stage that differs', 'Check integer widths, rounding and saturation there', 'Fix it and add the vector to the regression suite'], 'Bisect the pipeline, then protect the fix.'),
      info('Follow-ups to expect', '- "What is a MISRA deviation?" A documented, justified and approved exception to a rule.\n- "What is a safe state?" The condition the function enters when a failure is detected, with no unreasonable risk.\n- "How do you test an ML model for a car?" Requirement-based tests, recorded data, simulation, HIL, vehicle tests.\n- "What does ASIL decide?" How rigorous development and verification must be.'),
      mc('"What is a MISRA deviation?"', ['A documented, justified and approved exception to a coding rule', 'A bug that MISRA found', 'A faster coding style', 'A CAN error frame'], 'Rules may be broken only with a recorded reason.'),
      match('Match the term', [['Watchdog', 'Resets the system or triggers a safe state if the software stops running normally'], ['Safe state', 'Condition entered on failure with no unreasonable risk'], ['Plausibility check', 'Tests whether a value is physically possible'], ['WCET', 'Longest time a task can take']]),
      type('A task runs every 20 ms with a WCET of 5 ms. What is its CPU utilisation in percent?', ['25', '25%'], '5 / 20 = 0.25.'),
      mc('"Why not just average many PC runs to get WCET?"', ['The average hides the worst case, and a PC differs from the target in caches, pipeline and clock', 'PC runs are illegal', 'Averages are always too high', 'The target has no clock'], 'Worst-case evidence must come from the target and cover worst-case paths.'),
      tf('ISO 26262 mainly prescribes a development and safety-assurance process, not one particular algorithm.', true, 'You show that your process and safety argument meet the standard.'))
  ],

  'cloud-deploy': [
    L('Containers',
      info('"It works on my machine"', 'Your model needs a specific Python, specific library versions and system packages. On another machine something is always different.\n\nA **container image** packages your code together with all of that. It runs the same on your laptop, a colleague’s PC and a cloud server.'),
      match('Match the term', [['Image', 'A packaged, read-only snapshot of app and dependencies'], ['Container', 'A running instance of an image'], ['Dockerfile', 'The recipe that builds an image'], ['Registry', 'Where images are stored and shared']]),
      order('Order a simple Dockerfile', ['FROM python:3.12-slim', 'COPY requirements.txt .', 'RUN pip install -r requirements.txt', 'COPY . .', 'CMD ["uvicorn", "app:app", "--host", "0.0.0.0"]'], 'Dependencies before code, so rebuilds reuse the cached layer.'),
      mc('Why copy requirements.txt and install before copying the rest of the code?', ['Layer caching: dependencies are not reinstalled when only code changes', 'Docker requires alphabetical order', 'It makes the image smaller', 'It encrypts the code'], 'Each instruction is a cached layer.'),
      tf('A container includes its own full operating-system kernel, like a virtual machine.', false, 'Containers share the host kernel, which makes them light and fast to start.'),
      mc('Where should the model be loaded in an API service?', ['Once at start-up', 'On every request', 'In the Dockerfile CMD line', 'In the client'], 'Loading per request would add seconds of latency.'),
      fillc('@app.get("/___")\ndef health():\n    return {"ok": True}', ['health', 'predict', 'train', 'delete'], 'Orchestrators call a health endpoint to know whether to send traffic.')),

    L('Where to run it',
      info('Three common choices', '**Serverless** (functions, scale-to-zero containers): nothing to manage, pay per request, but cold starts and limits.\n\n**Managed ML endpoint** (SageMaker, Vertex AI, Azure ML): upload a model, get an autoscaled URL.\n\n**Kubernetes**: you run containers on a cluster with full control. Powerful, and it needs skilled operators.'),
      mc('An internal tool is called 20 times a day. Best fit?', ['Serverless / scale to zero', 'A 10-node GPU cluster', 'Three always-on VMs', 'A mainframe'], 'Pay only when it is used; a cold start is acceptable.'),
      mc('A product serves 2,000 requests per second with GPUs and several models. Best fit?', ['Kubernetes or a managed GPU endpoint with autoscaling', 'A single laptop', 'Serverless functions with a 15-minute limit', 'A spreadsheet'], 'Steady heavy load justifies dedicated, well-utilised capacity.'),
      match('Match the cloud to its ML platform', [['AWS', 'SageMaker'], ['Google Cloud', 'Vertex AI'], ['Microsoft Azure', 'Azure Machine Learning'], ['Any cloud', 'Kubernetes']]),
      info('Cold starts', 'A **cold start** is the delay when a new instance must boot, pull the image and load the model before it can answer. For a large model that can be tens of seconds.\n\nFixes: keep a minimum number of warm instances, shrink the image, load the model from fast storage.'),
      mc('Users complain that the first request after a quiet period takes 20 seconds. Cause?', ['Cold start after scaling to zero', 'A slow CPU', 'Too many replicas', 'A bug in the model'], 'Keep at least one warm instance if that latency is unacceptable.'),
      tf('Batch prediction jobs are a good choice when results are not needed immediately.', true, 'They are cheaper and simpler than an always-on endpoint.'),
      mc('Which is NOT a reason to pick a managed endpoint over self-managed Kubernetes?', ['Lowest possible unit cost at very large scale', 'Faster to get live', 'Built-in monitoring and scaling', 'Less to operate'], 'Managed services charge a premium; at scale, self-managed can be cheaper.')),

    L('Scaling and reliability',
      info('Horizontal autoscaling', 'Add or remove replicas to follow load. Kubernetes uses:\n\n```\ndesired = ceil(current * metric / target)\n```\n\nIf 4 pods run at 90% CPU and the target is 60%, it wants `ceil(4 * 90 / 60) = 6` pods.'),
      type('3 pods at 80% CPU, target 40%. How many pods does the autoscaler want?', ['6'], 'ceil(3 * 80 / 40) = 6.'),
      mc('For a GPU model server, which metric is usually better to scale on than CPU?', ['Requests per second or queue length', 'Disk size', 'Number of developers', 'Image name'], 'CPU says little when the work is on the GPU.'),
      match('Match the probe or pattern', [['Readiness probe', 'Is this pod ready to receive traffic?'], ['Liveness probe', 'Is it stuck and should be restarted?'], ['Rate limiting', 'Protect the service from overload'], ['Timeout and retry', 'Survive slow or failed calls']]),
      mc('A model server pod reports ready before its model has loaded. What happens?', ['Requests sent to it fail or hang', 'It scales faster', 'Nothing', 'The model loads sooner'], 'Readiness must reflect "model loaded".'),
      info('Releasing safely', '**Rolling update:** replace pods gradually. **Blue-green:** run old and new side by side and switch traffic. **Canary:** send a small share of traffic to the new version first.\n\nAll three need a fast **rollback**.'),
      mc('You send 5% of traffic to a new model version and watch error rate and latency. This is a…', ['Canary release', 'Blue-green release', 'Cold start', 'Batch job'], 'Expand only if the metrics stay healthy.'),
      fill('A token bucket holding 10 tokens that refills at 2 per second allows a burst of ___ requests.', ['10', '2', '20', '5'], 'Capacity sets the burst, rate sets the long-run average.'),
      tf('Retries without a limit or back-off can make an outage worse.', true, 'They multiply load on a struggling service. Use capped, exponential back-off.')),

    L('Cost, security and interview level',
      info('Cloud bills grow quietly', 'The big levers:\n\n- **Right-size and autoscale;** scale to zero when idle.\n- **Spot / preemptible** instances for training and batch work.\n- **Reserved** capacity for steady load.\n- **Cheaper inference:** quantise, distil, batch, cache.\n- Track **cost per request** and set budget alerts.'),
      mc('Which workload suits spot (preemptible) instances?', ['A training job that checkpoints regularly', 'A payment API with strict uptime', 'The primary database', 'A real-time safety service'], 'It can be interrupted and resumed.'),
      mc('GPU utilisation of your endpoint is 8%. Best cost action?', ['Smaller or fewer instances, dynamic batching, or scale to zero', 'Add more GPUs', 'Raise the timeout', 'Turn off monitoring'], 'You are paying for idle hardware.'),
      match('Match the security practice', [['Secrets manager', 'Keep API keys out of code and images'], ['Least privilege', 'Each service gets only the access it needs'], ['Private networking', 'Do not expose internal services publicly'], ['Authentication', 'Every endpoint checks who is calling']]),
      tf('It is fine to bake an API key into a Docker image if the registry is private.', false, 'Images are copied and cached widely. Inject secrets at run time.'),
      info('Infrastructure as code and CI/CD', 'Describe servers, networks and permissions in files (for example Terraform) and keep them in Git. A pipeline then tests, builds the image, and deploys it.\n\nBenefits: repeatable environments, reviewable changes, easy rollback.'),
      order('Order a CI/CD pipeline for a model service', ['Run unit tests', 'Build the container image', 'Push the image to the registry', 'Deploy to staging and run checks', 'Roll out gradually to production'], 'Nothing reaches production without passing the earlier stages.'),
      mc('Interview: "Design the deployment for a new model API." What should you ask first?', ['Traffic pattern, latency target, model size and whether GPUs are needed', 'Which editor the team uses', 'The CEO’s favourite cloud', 'How many lines of code'], 'Requirements decide between serverless, managed and Kubernetes.'),
      mc('Latency p50 is 40 ms but p99 is 2 s. What does that suggest?', ['A tail problem: cold starts, queueing or occasional slow dependencies', 'The service is healthy', 'The average is wrong', 'The model is too accurate'], 'Users feel the tail. Investigate what the slow requests have in common.')),

    L('Stateless services, queues and limits',
      info('Stateless services', 'A **stateless** service keeps nothing important in its own memory or disk between requests. Model files come from shared storage, sessions live in an external store, results go to a database.\n\nThen any replica can serve any request, and any replica can be killed and replaced at any time. That is what makes horizontal scaling safe.'),
      mc('Which design breaks when you scale from 1 to 5 replicas?', ['Each replica keeps user sessions in its own memory', 'Each replica loads the model from shared storage at start-up', 'Each replica logs to standard output', 'Each replica has a health endpoint'], 'The next request may reach a replica that has never seen that session.'),
      info('Queues for slow work', 'A job that takes minutes should not hold an HTTP connection open. The client submits it and gets a **job ID**. A **queue** buffers the jobs, **workers** take them one by one, and the result is stored. The client polls a status endpoint or receives a callback.\n\nA queue also absorbs bursts: work waits instead of being dropped.'),
      mc('A video analysis takes 2 minutes and the gateway times out after 30 seconds. Best design?', ['Return a job ID at once; queue the work; workers process it; the client polls or gets a callback', 'Give the pod more CPU', 'Retry the request until it works', 'Compress the response'], 'Asynchronous jobs decouple the request from the processing time.'),
      type('50 jobs arrive per minute and one worker finishes 10 jobs per minute. How many workers keep up?', ['5'], '50 / 10 = 5.'),
      match('Match the term', [['Resource request', 'Amount the scheduler reserves for the container'], ['Resource limit', 'Ceiling the container may not exceed'], ['Idempotency key', 'Lets a retried request be recognised as the same one'], ['Graceful shutdown', 'Finish in-flight requests after a stop signal before exiting']]),
      tf('A container that exceeds its memory limit is typically killed by the platform.', true, 'It shows up as OOMKilled and restarts.'),
      mc('A pod receives a stop signal in the middle of a rolling update, with requests in flight. What should the server do?', ['Stop accepting new requests, finish the ones in flight, then exit', 'Exit immediately', 'Ignore the signal', 'Delete the model'], 'Graceful shutdown avoids failed requests during releases.'),
      mc('A client retries a "create job" request after a timeout, and two jobs are created and billed. How do you prevent it?', ['Send an idempotency key so the server recognises the retry', 'Disable all retries and timeouts', 'Make the server slower', 'Use a bigger queue'], 'Retries are safe only if repeating the request has the same effect as doing it once.')),

    L('Container and API bugs',
      info('Bugs that only appear in production', 'The model works on a laptop and fails behind a load balancer. Typical culprits:\n\n- loading the model **on every request**;\n- a **blocking** call inside an async handler, which freezes every other request;\n- the server listening on `127.0.0.1`, unreachable from outside the container;\n- unpinned dependencies, so today’s build differs from last month’s.'),
      mc('Why is this endpoint slow, even though the model is fast?', ['The model is loaded from disk on every request', 'tolist is slow', 'The request class is too large', 'POST is slower than GET'], 'Load the model once at start-up and reuse it.', '@app.post("/predict")\ndef predict(req: Req):\n    model = torch.load("model.pt")\n    return {"y": model(req.x).tolist()}'),
      mc('While one prediction runs, every other request waits. Why?', ['A CPU-heavy call inside an async def handler blocks the event loop', 'async handlers are slower than sync ones by design', 'The request body is too large', 'The model is quantised'], 'Use a normal def (run in a thread pool) or move the work to a worker process.', '@app.post("/predict")\nasync def predict(req: Req):\n    y = model(req.x)\n    return {"y": y.tolist()}'),
      info('Images, binding and limits', 'A server started with the default host `127.0.0.1` listens only **inside** the container. Publishing the port does not help; bind to `0.0.0.0`.\n\nPin versions of the base image and of every package, never `latest`. Memory limits count **per container**: if each of two workers loads a 1.5 GB model, the pod needs about 3 GB.'),
      mc('The container starts, the logs say the server listens on 127.0.0.1:8000, and the published port refuses connections. Cause?', ['The server only listens on the loopback interface inside the container', 'The image is too small', 'The model is not loaded', 'The registry is down'], 'Start it with --host 0.0.0.0.'),
      fillc('uvicorn app:app --host ___ --port 8000', ['0.0.0.0', '127.0.0.1', 'localhost', '255.255.255.255'], '0.0.0.0 means all interfaces, so traffic from outside can reach it.'),
      mc('A build that worked last month now fails, though no code changed. The Dockerfile says `FROM python:latest` and `pip install torch`. Likely cause?', ['Unpinned versions changed underneath you', 'Docker deleted your code', 'The registry is encrypted', 'The CPU is slower'], 'Pin the base image tag and the package versions.'),
      order('Order a response to pods that crash-loop after a deploy', ['Look at the pod status and the restart reason', 'Read the logs of the failed container', 'Check recent changes: image tag, config, secrets', 'Reproduce the image locally with the same settings', 'Fix and redeploy gradually'], 'Evidence first, then reproduce, then fix.'),
      type('Two uvicorn workers each load a 1.5 GB model. How many GB does the pod need for the models alone?', ['3', '3 gb', '3gb'], '2 × 1.5 = 3 GB.'),
      mc('The pod has a 2 GB memory limit and keeps restarting as OOMKilled. Best fix?', ['Run one worker per pod and scale out with more pods, or give the pod enough memory', 'Remove the health endpoint', 'Raise the log level', 'Add more CPU only'], 'The models need 3 GB, which does not fit a 2 GB limit.')),

    L('Case study: real-time fraud scoring',
      info('The brief', 'A payment company scores every card transaction before approval. Budget: **100 ms** end to end, of which the model needs about 5 ms. Average load is 200 requests per second, but sales events reach **1,500 per second**. If the service is down, payments are approved or declined blindly.\n\nReal-time scoring of this kind is a classic production ML use. The numbers are illustrative. You make the decisions.'),
      type('At the peak of 1,500 requests per second, each pod handles 150 requests per second at its target load. How many pods are needed?', ['10'], '1500 / 150 = 10.'),
      mc('Which hosting fits?', ['Autoscaled Kubernetes or a managed endpoint with a minimum number of warm replicas', 'Scale-to-zero serverless, since cold starts would break a 100 ms budget', 'One big VM with no redundancy', 'A batch job every night'], 'A steady, latency-critical service needs warm, redundant capacity.'),
      info('Features and fallbacks', 'The model needs features such as a customer’s recent spending. They come from a fast store, and every lookup adds latency. Plan for it to be slow or down:\n\n- set a **short timeout** on each lookup;\n- have a **fallback**: default features or a simple rules-based score;\n- never let a slow dependency consume the whole budget.'),
      mc('The feature store sometimes takes 300 ms. What do you do?', ['Set a short timeout (for example 30 ms) and fall back to default features or a rules-based score', 'Raise the timeout to 1 second', 'Retry five times immediately', 'Remove the 100 ms budget'], 'The budget is a requirement; degrade gracefully instead of waiting.'),
      mc('How can you test a new model on live traffic with no risk to customers at first?', ['Shadow mode: score in parallel and log, but do not act on the result', 'Switch 50% of traffic to it', 'Replace the old model overnight', 'Run it only on your laptop'], 'Shadow results can be compared with the live model before any decision depends on them.'),
      order('Order the release', ['Evaluate offline on held-out data', 'Deploy in shadow mode and compare with the live model', 'Canary with 5% of traffic', 'Watch errors, latency and approval rates', 'Roll out fully, keeping rollback ready'], 'Each stage limits the damage if the model is wrong.'),
      tf('A model with better offline accuracy can safely go to 100% of traffic immediately.', false, 'Live data, latency and side effects can differ from the offline test, so release gradually.'),
      mc('Confirmed fraud labels arrive weeks late. Which signal can you watch immediately?', ['Drift in the input features and score distribution, plus approval rate', 'Training accuracy', 'Number of Git commits', 'Docker image size'], 'Delayed labels mean you need early-warning proxies.'),
      type('A 99.9% availability target over a 30-day month allows about how many minutes of downtime? Round down.', ['43', '43 min', '43 minutes', '43.2'], '30 × 24 × 60 = 43,200 minutes, and 0.1% of that is 43.2.')),

    L('Interview drill: cloud deployment',
      info('What interviewers probe', 'Cloud questions are **design questions**. They want to see you ask about requirements, pick a simple architecture, and think about failure, cost and release safety.\n\nExpect "how do you roll back?", "how do you know it still works?" and "what if traffic grows ten times?".'),
      mc('"How do you roll back a bad model release?" Strongest answer?', ['Keep versioned, immutable images and models, shift traffic back to the previous version, and rehearse it', 'Retrain the model quickly', 'Edit the files on the server', 'Hope the new version improves'], 'Fast rollback depends on keeping the previous version ready.'),
      mc('"What is the difference between scaling out and scaling up?"', ['Out adds more replicas; up gives one machine more resources', 'Out is cheaper and up is free', 'They are the same', 'Out needs a GPU, up does not'], 'Scaling out also gives redundancy.'),
      order('Order a strong answer to "The API is slow. What do you do?"', ['Ask when it is slow and for which percentile', 'Use metrics and traces to find the slow stage', 'Fix the largest contributor: model, preprocessing, network or cold starts', 'Load-test the fix', 'Re-measure in production'], 'Locate before you change.'),
      info('Follow-ups to expect', '- "How do you know the model is still good?" Monitor input drift, prediction distribution and delayed outcomes.\n- "What would you do first with ten times the traffic?" Load-test to find the current bottleneck.\n- "How do you keep secrets safe?" A secrets manager and runtime injection, never in the image.\n- "What is your cost lever?" Right-size, autoscale, batch, cache and spot capacity for fault-tolerant work.'),
      mc('"How do you know a deployed model is still good?"', ['Monitor input drift and prediction distributions, track outcomes when labels arrive, and alert on changes', 'It was accurate in training, so it is fine', 'Wait for customers to complain', 'Check the container size'], 'Models degrade silently when the data changes.'),
      match('Match the term', [['p99 latency', 'Time under which 99% of requests finish'], ['SLO', 'A target for service quality, such as 99.9% availability'], ['Error budget', 'The unreliability the SLO still allows'], ['Idempotent request', 'Repeating it has the same effect as doing it once']]),
      type('A 99.9% availability target over a 1,000-minute period allows how many minutes of downtime?', ['1', '1 min', '1 minute'], '0.1% of 1,000 is 1.'),
      mc('"Traffic will be ten times higher next week." What do you do first?', ['Load-test to find the current bottleneck, then add capacity, limits and fallbacks', 'Buy ten times the servers', 'Wait and see', 'Rewrite the model'], 'Measure before you spend.'),
      tf('A strong design answer starts by asking about requirements.', true, 'Traffic, latency, availability and budget decide between serverless, managed and Kubernetes.'))
  ]
};
